  CONSTRAINT "ck_sqlite_ts__tenants__updated_at" CHECK ("updated_at" IS NULL OR ("updated_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z')),
