  CONSTRAINT "users_tenant_id_email_key" UNIQUE ("tenant_id", "email"),
  CONSTRAINT "ck_sqlite_len_255__users__name" CHECK (length("name") <= 255),
  CONSTRAINT "ck_sqlite_len_320__users__email" CHECK (length("email") <= 320),
  CONSTRAINT "ck_sqlite_len_255__users__password_hash" CHECK (length("password_hash") <= 255),
  CONSTRAINT "ck_sqlite_len_20__users__role" CHECK (length("role") <= 20),
  CONSTRAINT "ck_sqlite_bool__users__active" CHECK ("active" IN (0, 1)),
  CONSTRAINT "ck_sqlite_json__users__permissions" CHECK ("permissions" IS NULL OR (json_valid("permissions"))),
  CONSTRAINT "ck_sqlite_ts__users__created_at" CHECK ("created_at" IS NULL OR ("created_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z')),
  CONSTRAINT "ck_sqlite_ts__users__updated_at" CHECK ("updated_at" IS NULL OR ("updated_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z')),
  CONSTRAINT "ck_sqlite_bool__users__is_license_owner" CHECK ("is_license_owner" IN (0, 1)),
  CONSTRAINT "ck_sqlite_len_255__users__pin_hash" CHECK (length("pin_hash") <= 255),
  CONSTRAINT "ck_sqlite_ts__users__tokens_revoked_before" CHECK ("tokens_revoked_before" IS NULL OR ("tokens_revoked_before" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z'))
) STRICT;

CREATE TABLE "vouchers" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (random() & 3), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  "tenant_id" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "number" TEXT NOT NULL,
  "date" TEXT NOT NULL,
  "party_id" TEXT NOT NULL,
  "party_kind" TEXT NOT NULL,
  "invoice_id" TEXT,
  "amount" INTEGER NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'SYP',
  "method" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'active',
