  "cancelled_at" TEXT,
  "cancelled_by" TEXT,
  "exchange_rate" INTEGER,
  "base_amount" INTEGER,
  "discount" INTEGER NOT NULL DEFAULT 0,
  "applied_amount" INTEGER,
  "client_operation_id" TEXT,
