  CONSTRAINT "ck_sqlite_len_10__vouchers__kind" CHECK (length("kind") <= 10),
  CONSTRAINT "ck_sqlite_len_50__vouchers__number" CHECK (length("number") <= 50),
  CONSTRAINT "ck_sqlite_date__vouchers__date" CHECK ("date" IS NULL OR (length("date") = 10 AND date("date") = "date")),
  CONSTRAINT "ck_sqlite_len_10__vouchers__party_kind" CHECK (length("party_kind") <= 10),
  CONSTRAINT "ck_sqlite_len_3__vouchers__currency" CHECK (length("currency") <= 3),
  CONSTRAINT "ck_sqlite_len_20__vouchers__method" CHECK (length("method") <= 20),
  CONSTRAINT "ck_sqlite_len_20__vouchers__status" CHECK (length("status") <= 20),
  CONSTRAINT "ck_sqlite_json__vouchers__attachments" CHECK ("attachments" IS NULL OR (json_valid("attachments"))),
  CONSTRAINT "ck_sqlite_ts__vouchers__created_at" CHECK ("created_at" IS NULL OR ("created_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z')),
  CONSTRAINT "ck_sqlite_ts__vouchers__updated_at" CHECK ("updated_at" IS NULL OR ("updated_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z')),
  CONSTRAINT "ck_sqlite_ts__vouchers__cancelled_at" CHECK ("cancelled_at" IS NULL OR ("cancelled_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z'))
) STRICT;

